#include <iostream>
using namespace std;


class Solution {
public:
    ListNode* swapNodes(ListNode* head, int k) {
        ListNode* first = head, * second = head, * curr = head;
        int count = 1;

        while (curr) {
            if (count < k) first = first->next;
            if (count > k) second = second->next;
            curr = curr->next;
            count++;
        }

        swap(first->val, second->val);
        return head;
    }
};
